#!/usr/bin/env python3
"""Inspect PDF form fields"""

import pdfrw

# Read the PDF
pdf = pdfrw.PdfReader('/root/sc100-blank.pdf')

# Get the form fields
annotations = pdf.pages[0]['/Annots']

if annotations:
    print("Form fields found:")
    for i, annotation in enumerate(annotations):
        if annotation['/Subtype'] == '/Widget':
            field_name = annotation['/T']
            field_type = annotation['/FT'] if '/FT' in annotation else 'Unknown'
            print(f"{i}: {field_name} - Type: {field_type}")
else:
    print("No form fields found on first page")

# Check all pages
print(f"\nTotal pages: {len(pdf.pages)}")
for page_num, page in enumerate(pdf.pages):
    annots = page.get('/Annots')
    if annots:
        print(f"\nPage {page_num + 1} has {len(annots)} annotations")

