#!/usr/bin/env python3
"""Inspect PDF form fields using PyPDF2"""

from PyPDF2 import PdfReader

# Read the PDF
pdf = PdfReader('/root/sc100-blank.pdf')

print(f"Total pages: {len(pdf.pages)}")

# Try to get form fields
if '/AcroForm' in pdf.trailer['/Root']:
    print("\nForm found in PDF")
    fields = pdf.get_fields()
    if fields:
        print(f"\nTotal fields: {len(fields)}")
        print("\nField names:")
        for field_name in sorted(fields.keys()):
            field = fields[field_name]
            print(f"  {field_name}: {field.get('/FT', 'Unknown type')}")
    else:
        print("No fields extracted")
else:
    print("No AcroForm found")

